From f4a180247e06c69e7d8fac4eb14d172c3a5d43a3 Mon Sep 17 00:00:00 2001
From: Guenter Roeck <linux@roeck-us.net>
Date: Tue, 9 Jul 2024 15:41:07 -0700
Subject: [PATCH] hwmon: (g762) Initialize fans after configuring clock

Adding support for G761 included adding support for an internal clock.
Enabling the internal clock requires setting a bit in the FAN_CMD2
register. This is implemented in g762_fan_init(). However, g762_fan_init()
is called before clock support is selected, and the flag indicating that
the internal clock should be used is not yet set.

Initialize the clock before initializing the fan to solve the problem.
While at it, also add "g7621" to the i2c_device_id array.

Cc: Christian Marangi <ansuelsmth@gmail.com>
Fixes: 6ce402327a6f ("hwmon: g672: add support for g761")
Signed-off-by: Guenter Roeck <linux@roeck-us.net>

diff --git a/drivers/hwmon/g762.c b/drivers/hwmon/g762.c
index a00cf3245eec..4fa3aa1271da 100644
--- a/drivers/hwmon/g762.c
+++ b/drivers/hwmon/g762.c
@@ -44,6 +44,7 @@
 #define DRVNAME "g762"

 static const struct i2c_device_id g762_id[] = {
+	{ "g761" },
 	{ "g762" },
 	{ "g763" },
 	{ }
@@ -1083,15 +1084,16 @@ static int g762_probe(struct i2c_client *client)
 	data->client = client;
 	mutex_init(&data->update_lock);

-	/* Enable fan failure detection and fan out of control protection */
-	ret = g762_fan_init(dev);
+	/* Get configuration via DT ... */
+	ret = g762_of_clock_enable(client);
 	if (ret)
 		return ret;

-	/* Get configuration via DT ... */
-	ret = g762_of_clock_enable(client);
+	/* Enable fan failure detection and fan out of control protection */
+	ret = g762_fan_init(dev);
 	if (ret)
 		return ret;
+
 	ret = g762_of_prop_import(client);
 	if (ret)
 		return ret;
-- 
2.25.1

Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
hwmon: (g762) Initialize fans after configuring clock

Adding support for G761 included adding support for an internal clock.
Enabling the internal clock requires setting a bit in the FAN_CMD2
register. This is implemented in g762_fan_init(). However, g762_fan_init()
is called before clock support is selected, and the flag indicating that
the internal clock should be used is not yet set.

Initialize the clock before initializing the fan to solve the problem.
While at it, also add "g7621" to the i2c_device_id array.

Cc: Christian Marangi <ansuelsmth@gmail.com>
Fixes: 6ce402327a6f ("hwmon: g672: add support for g761")
Signed-off-by: Guenter Roeck <linux@roeck-us.net>

Here is the root cause:
The bug was caused by the `g762_fan_init()` function being called before the internal clock was enabled. This resulted in the fan being initialized without the necessary clock configuration, leading to potential malfunction or incorrect operation of the fan control system.

Here is the patch:

 static const struct i2c_device_id g762_id[] = {
+	{ "g761" },
 	{ "g762" },
 	{ "g763" },

 static int g762_probe(struct i2c_client *client)
 {
 	struct device *dev = &client->dev;
 	struct device *hwmon_dev;
 	struct g762_data *data;
 	int ret;

 	if (!i2c_check_functionality(client->adapter,
 				     I2C_FUNC_SMBUS_BYTE_DATA))
 		return -ENODEV;

 	data = devm_kzalloc(dev, sizeof(struct g762_data), GFP_KERNEL);
 	if (!data)
 		return -ENOMEM;

 	i2c_set_clientdata(client, data);
 	data->client = client;
 	mutex_init(&data->update_lock);

-	/* Enable fan failure detection and fan out of control protection */
-	ret = g762_fan_init(dev);
+	/* Get configuration via DT ... */
+	ret = g762_of_clock_enable(client);
 	if (ret)
 		return ret;

-	/* Get configuration via DT ... */
-	ret = g762_of_clock_enable(client);
+	/* Enable fan failure detection and fan out of control protection */
+	ret = g762_fan_init(dev);
 	if (ret)
 		return ret;
+
 	ret = g762_of_prop_import(client);
 	if (ret)
 		return ret;
 	/* ... or platform_data */
 	ret = g762_pdata_prop_import(client);
 	if (ret)
 		return ret;

 	hwmon_dev = devm_hwmon_device_register_with_groups(dev, client->name,
 							    data, g762_groups);
 	return PTR_ERR_OR_ZERO(hwmon_dev);
 }



